css:
.certificate-container {
    font-family: "Inter" sans-serif;
    font-size: 20px;
}

.inner-border {
    border: 8px solid #0089FF;
    border-radius: 8px;
    text-align: center;
    padding: 6rem 4rem;
    background-color: #FFFFFF;
}

.certificate-logo {
    height: 3rem;
    margin-right: 0.5rem;
}

.certificate-name {
    font-size: 2rem;
    font-weight: 500;
    color: #192734;
    margin-bottom: 0.5rem;
}

.certificate-footer {
    margin: 4rem auto 0;
    width: 70%;
    text-align: center;
}

.certificate-footer-item {
    color: #192734;
}

.cursive-font {
    font-family: cursive;
    font-weight: 600;
}

.certificate-divider {
    margin: 0.5rem 0;
}

.certificate-expiry {
    margin-left: 2rem;
}
